using Watchpoint.Kernel.Results;

namespace Watchpoint.Registry.Contracts;

/// <summary>
/// Domain errors generated by the Registry module (REG §9). Codes are the API and UI contract: callers key plain
/// language problems on them, so every violation of a documented invariant returns one of these, never a generic one.
/// </summary>
public static class RegistryErrors
{
    /// <summary><c>registry.site.not_initialised</c>: no site has ever been configured for this installation (R1).</summary>
    public static Error SiteNotInitialised() => Error.Unavailable("registry.site.not_initialised");

    /// <summary><c>registry.location.not_found</c>.</summary>
    public static Error LocationNotFound(string id) => Error.NotFound("registry.location.not_found", ("id", id));

    /// <summary><c>registry.server.not_found</c>.</summary>
    public static Error ServerNotFound(string id) => Error.NotFound("registry.server.not_found", ("id", id));

    /// <summary><c>registry.device.not_found</c>.</summary>
    public static Error DeviceNotFound(string id) => Error.NotFound("registry.device.not_found", ("id", id));

    /// <summary><c>registry.tag.not_found</c>.</summary>
    public static Error TagNotFound(string id) => Error.NotFound("registry.tag.not_found", ("id", id));

    /// <summary><c>registry.link.not_found</c>.</summary>
    public static Error LinkNotFound(string id) => Error.NotFound("registry.link.not_found", ("id", id));

    /// <summary><c>registry.custom_field.not_found</c>.</summary>
    public static Error CustomFieldNotFound(string id) => Error.NotFound("registry.custom_field.not_found", ("id", id));

    /// <summary>
    /// <c>registry.tag_family.not_found</c>: additive to the REG §9 catalogue (<see cref="RegistryChange.DeleteTagFamily"/>
    /// is not in the REG §6 sketch either).
    /// </summary>
    public static Error TagFamilyNotFound(string id) => Error.NotFound("registry.tag_family.not_found", ("id", id));

    /// <summary><c>registry.location.cycle</c> (R2).</summary>
    public static Error LocationCycle() => Error.Create(ErrorKind.Validation, "registry.location.cycle");

    /// <summary><c>registry.location.too_deep</c> (R2).</summary>
    public static Error LocationTooDeep(int max) => Error.Create(ErrorKind.Validation, "registry.location.too_deep", ("max", max));

    /// <summary><c>registry.location.duplicate_name</c> (R2): a sibling location already has this name.</summary>
    public static Error LocationDuplicateName(string name) => Error.Create(ErrorKind.Validation, "registry.location.duplicate_name", ("name", name));

    /// <summary><c>registry.location.not_empty</c> (REG §6 step 6): deleting a location with children or objects requires <c>ReassignTo</c>.</summary>
    public static Error LocationNotEmpty(int children, int objects) =>
        Error.Create(ErrorKind.Conflict, "registry.location.not_empty", ("children", children), ("objects", objects));

    /// <summary><c>registry.location.root_immutable</c>: the root location cannot be moved or deleted.</summary>
    public static Error LocationRootImmutable() => Error.Create(ErrorKind.Validation, "registry.location.root_immutable");

    /// <summary><c>registry.tag.duplicate_key</c> (R3).</summary>
    public static Error TagDuplicateKey(string key) => Error.Create(ErrorKind.Validation, "registry.tag.duplicate_key", ("key", key));

    /// <summary><c>registry.tag.family_exclusive</c> (R3): the target already holds a tag of this exclusive family.</summary>
    public static Error TagFamilyExclusive(string family) => Error.Create(ErrorKind.Validation, "registry.tag.family_exclusive", ("family", family));

    /// <summary><c>registry.type.invalid_role</c> (R4): the type resolves but with another role.</summary>
    public static Error TypeInvalidRole(string typeId, string expectedRole) =>
        Error.Create(ErrorKind.Validation, "registry.type.invalid_role", ("typeId", typeId), ("expectedRole", expectedRole));

    /// <summary><c>registry.device.duplicate_native_id</c> (R5).</summary>
    public static Error DeviceDuplicateNativeId(string nativeId) => Error.Create(ErrorKind.Validation, "registry.device.duplicate_native_id", ("nativeId", nativeId));

    /// <summary><c>registry.server.duplicate_native_id</c> (R5).</summary>
    public static Error ServerDuplicateNativeId(string nativeId) => Error.Create(ErrorKind.Validation, "registry.server.duplicate_native_id", ("nativeId", nativeId));

    /// <summary>
    /// <c>registry.device.parent_invalid</c> (R6). <paramref name="reason"/> is one of <c>otherServer</c>,
    /// <c>typeNotAllowed</c>, <c>cycle</c>, <c>tooDeep</c>.
    /// </summary>
    public static Error DeviceParentInvalid(string reason) => Error.Create(ErrorKind.Validation, "registry.device.parent_invalid", ("reason", reason));

    /// <summary>
    /// <c>registry.server.parent_invalid</c> (R7). <paramref name="reason"/> is one of <c>otherConnection</c>,
    /// <c>cycle</c>, <c>tooDeep</c>.
    /// </summary>
    public static Error ServerParentInvalid(string reason) => Error.Create(ErrorKind.Validation, "registry.server.parent_invalid", ("reason", reason));

    /// <summary><c>registry.device.has_children</c> (REG §6 step 8): deleting a device with children requires <c>DeleteChildren</c>.</summary>
    public static Error DeviceHasChildren(int count) => Error.Create(ErrorKind.Conflict, "registry.device.has_children", ("count", count));

    /// <summary><c>registry.server.not_empty</c> (REG §6 step 7): deleting a server with devices requires <c>DeleteDevices</c>.</summary>
    public static Error ServerNotEmpty(int devices) => Error.Create(ErrorKind.Conflict, "registry.server.not_empty", ("devices", devices));

    /// <summary>
    /// <c>registry.link.invalid</c> (R9). <paramref name="reason"/> is one of <c>sourceNotFound</c>,
    /// <c>targetNotFound</c>, <c>duplicate</c>, <c>selfLink</c>.
    /// </summary>
    public static Error LinkInvalid(string reason) => Error.Create(ErrorKind.Validation, "registry.link.invalid", ("reason", reason));

    /// <summary><c>registry.batch.too_large</c> (REG §6): the batch exceeds the change-count limit. T1.09c adds the record byte-size cause (<c>bytes</c>).</summary>
    public static Error BatchTooLarge(int max) => Error.Create(ErrorKind.Validation, "registry.batch.too_large", ("max", max));

    /// <summary>Optimistic concurrency version conflict error (<c>common.version.conflict</c>).</summary>
    public static Error VersionConflict(string entityType, string id, long currentVersion, long? expectedVersion) =>
        Error.Conflict("common.version.conflict", ("entityType", entityType), ("id", id), ("currentVersion", currentVersion), ("expectedVersion", expectedVersion ?? 0L));

    /// <summary>Reconcile warning code for major type changes.</summary>
    public const string ReconcileTypeMajorChange = "registry.reconcile.type_major_change";

    /// <summary>Reconcile warning code for unresolved links.</summary>
    public const string ReconcileLinkUnresolved = "registry.reconcile.link_unresolved";
}
